 "differences": [
  {
   "topic": "Table and tree",
   "mac": "Table, Tree",
   "win": "ListView, TreeView",
   "why": "The native classes are NSTableView and NSOutlineView, and \"Table\" is the usual Mac word."
  },
  {
   "topic": "Date field",
   "mac": "DatePicker(calendar=True)",
   "win": "DatePicker(long=True)",
   "why": "NSDatePicker has a calendar style; the long date format is a Windows option."
  },
  {
   "topic": "Slider ticks",
   "mac": "Slider(ticks=5, snap=True)",
   "win": "Slider(ticks=True, tick_frequency=...)",
   "why": "NSSlider counts its tick marks."
  },
  {
   "topic": "Dialog answers",
   "mac": "show_info(..., parent=win, then=handler)",
   "win": "show_info(..., parent=win)",
   "why": "On macOS a dialog with a parent is a sheet; it answers later, so `then=` gets the result."
  },
  {
   "topic": "Color result",
   "mac": "choose_color() returns '#RRGGBB'",
   "win": "choose_color() returns (r, g, b)",
   "why": "Same format as ColorWell.value."
  },
  {
   "topic": "Cancel in panels",
   "mac": "choose_color and choose_font have no Cancel",
   "win": "Both return None when cancelled",
   "why": "The system color and font panels have no OK and Cancel buttons."
  },
  {
   "topic": "Shortcut modifier",
   "mac": "\"Cmd+S\" (and \"Ctrl+S\" also means Cmd)",
   "win": "\"Ctrl+S\"",
   "why": "One shortcut string works on both systems."
  },
  {
   "topic": "Radio buttons",
   "mac": "RadioGroup(items)",
   "win": "single radio buttons",
   "why": "AppKit radio buttons need a group; one control with `items` is the shorter form."
  }
 ]
